from pathlib import Path
import json,gzip,statistics
root=Path('docs/mission-17-evidence/final')
read=lambda n:json.loads((root/n).read_text())
p=read('performance-summary.json');c=read('costs.json');s=read('soak-30min.json');v=read('validation.json');compiled=read('compiled-validation.json');media=read('media-validation.json')
assert s['isThirtyMinuteTest'] and s['wallSeconds']>=1800 and s['nativeSpanSeconds']>=1800
versions={'m16':'M16','m17c':'17C','after':'17D'};profiles={'eco':'Éco','balanced':'Équilibré','quality':'Qualité'}
rows=p['summary'];lines=['| Campagne | Profil | Vue | M16 médiane ms | 17C médiane ms | 17D médiane ms | Δ D/C | 17D P95 ms | 17D pic ms |','| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for campaign in ['colour','local-shadow']:
 for profile in ['eco','balanced','quality']:
  for view in ['bois','aerienne','berge'] if campaign=='colour' else ['bois']:
   cells=[next(x for x in rows if x['campaign']==campaign and x['profile']==profile and x['id']==view and x['version']==version) for version in ['m16','m17c','after']]
   a,b,d=cells;lines.append(f"| {'Couleur' if campaign=='colour' else 'Ombre locale'} | {profiles[profile]} | {view} | {a['medianMs']:.1f} | {b['medianMs']:.1f} | {d['medianMs']:.1f} | {(d['medianMs']/b['medianMs']-1)*100:+.1f} % | {d['p95Ms']:.1f} | {d['peakMs']:.1f} |")
alloc='Snapshots chauds du bois en couleur seule, dans l’ordre cumulatif de la campagne : géométries / programmes déjà rencontrés restent en cache. Les appels et triangles comprennent toute la scène, pas seulement les arbres. Les buffers et textures sont des allocations logiques instrumentées.\n\n| Profil | Version | Appels | Triangles | Textures | Buffers Mio | Textures estimées Mio |\n| --- | --- | ---: | ---: | ---: | ---: | ---: |\n'
for profile in ['eco','balanced','quality']:
 for version in ['m16','m17c','after']:
  x=next(x for x in rows if x['campaign']=='colour' and x['id']=='bois' and x['profile']==profile and x['version']==version);a=x['state']['game']['alloc'];alloc+=f"| {profiles[profile]} | {versions[version]} | {x['calls']} | {x['triangles']:.0f} | {x['textures']} | {a['bufferBytes']/1048576:.2f} | {a['textureBytesEstimate']/1048576:.2f} |\n"
wind=c['wind']['summary'];cost=f"Sur un arbre étalé isolé, le rendu synchronisé mesure **{wind[0]['medianMs']:.1f} / {wind[1]['medianMs']:.1f} / {wind[2]['medianMs']:.1f} ms** à la médiane sans vent / flexion simplifiée / hiérarchie complète, avec douze échantillons par mode en 640 × 480. Le P95 sans vent atteint {wind[0]['p95Ms']:.1f} ms : la variabilité interdit d’en déduire un coût exact de la forêt entière. La banque CPU seule a une médiane sous la résolution du chronomètre, un P95 de **{c['wind']['cpuSummary']['p95Ms']:.1f} ms** et une pointe de **{c['wind']['cpuSummary']['peakMs']:.1f} ms**, hors conversion half-float et transfert GPU.\n\nLe recalcul forcé des ombres est mesuré séparément, en **480 × 320** sur le bois, quatre rendus forcés alternés avec quatre cartes tenues par cellule. Les résultats sont peu échantillonnés et restent sensibles au logiciel :\n\n| Version | Profil | Forcé médiane ms | Carte tenue médiane ms | Arbres soumis / visibles |\n| --- | --- | ---: | ---: | ---: |\n"
# Upper observed median, consistent with the benchmark's quantile convention.
def med(a):return sorted(a)[len(a)//2]
for x in c['rows']:
 cost+=f"| {versions[x['version']]} | {profiles[x['profile']]} | {med([a['ms'] for a in x['samples'] if a['forced']]):.1f} | {med([a['ms'] for a in x['samples'] if not a['forced']]):.1f} | {x['visibleTreeInstancesOrIndividuals']} |\n"
cost+='\nMission 16 compte les instances de couronnes des cellules dont le volume passe le frustum ; 17C/17D comptent les individus dont le volume conservateur passe le frustum. Ce sont des compteurs de soumission, pas des feuilles réellement visibles après occultation. Les caps de casters et les allocations de chaque mesure figurent dans [le protocole et les données](mission-17-evidence/final/costs.json).'
trace=json.loads(gzip.decompress((root/'soak-trace.json.gz').read_bytes()));rr=trace['rows'];ff=trace['frames']
soak=f"Essai terminé sur le worktree détaché propre **`{s['commit'][:7]}`** : **{s['wallSeconds']/60:.2f} minutes murales**, **{s['nativeSpanSeconds']/60:.2f} minutes de frames natives**, **{s['metres']:.1f} m**, **{s['frameCount']} images**, {s['reversals']} inversions uniquement aux extrémités. Tous les échantillons restent marchables, avec un écart au sol maximal de **{s['maxGroundErrorM']*1000:.3f} mm** et un pas maximal de **{s['maxStepM']:.3f} m**. Aucune perte de contexte WebGL, erreur GL ou erreur JavaScript. Les empreintes de tous les fichiers source / publics suivis du worktree sont identiques avant et après.\n\nIntervalles natifs **logiciels**, 480 × 320 DPR 1 : **médiane {s['intervalMs']['median']:.1f} ms, P95 {s['intervalMs']['p95']:.1f} ms, pointe {s['intervalMs']['peak']:.1f} ms**. Ces valeurs incluent le streaming, les commandes de chapitre, les enregistrements et les GC. Elles révèlent des lenteurs et ne valident pas une promenade fluide. La limite M11 de reprise à une seconde s’applique sous les très longues pauses ; ce test ne prétend pas à une identité parfaite entre temps du vent et trente minutes murales.\n\n| Chapitre | Profil | Saison / météo | Vue | Cellules de sous-bois libérées |\n| --- | --- | --- | --- | ---: |\n"
for x in s['chapters']:soak+=f"| {x['phase']+1} | {profiles[x['profile']]} | {x['date']} · {x['weather']}{' · calme M11' if x['calmCommand'] else ''} | {x['mode']} | {x['reloadedDetailCells']} |\n"
heaps=s['heaps'];memory=f"Les **six cycles contrôlés** de création/destruction reviennent exactement aux mêmes compteurs : {v['disposal'][0]['after']['geometries']} géométries et {v['disposal'][0]['after']['textures']} textures logiques dans ce scénario. Buffers et textures estimées reviennent aussi aux mêmes octets. Il ne faut pas confondre ce retour contrôlé avec le chargement progressif du pilote entier.\n\nPendant la marche, les snapshots GPU vont de **{min(x['gpu']['geometries'] for x in rr)} à {max(x['gpu']['geometries'] for x in rr)} géométries**, **{min(x['gpu']['textures'] for x in rr)} à {max(x['gpu']['textures'] for x in rr)} textures**, et **{min(x['gpu']['programs'] for x in rr)} à {max(x['gpu']['programs'] for x in rr)} programmes**, selon profil, vue, premières utilisations et cellules de décor. Après GC, le tas JavaScript passe de **{heaps[0]['usedSize']/1048576:.2f} Mio** au départ à **{heaps[-1]['usedSize']/1048576:.2f} Mio** à la fin. Ces états à positions et saisons différentes ne suffisent pas à attribuer toute hausse à une fuite. Les allocations par chapitre et tous les points de GC sont conservés dans [le résultat prolongé](mission-17-evidence/final/soak-30min.json). Le son est ensuite disposé : contexte **fermé**, **zéro nœud** restant."
warmHeaps=[h['usedSize']/1048576 for h in heaps if h['seconds']>=300]
memory+=f" Après les cinq premières minutes, les points de GC oscillent entre **{min(warmHeaps):.2f} et {max(warmHeaps):.2f} Mio** ; aucune dérive continue nette n’est observée sur cet essai."
# Include measured calm/shadow reuse instead of promising a fixed refresh rate.
calm=[x for x in rr if x['phase']==4]
if calm:memory+=f"\n\nLe chapitre calme atteint une entrée M11 minimale de **{min(x['state']['game']['climate']['effectiveMeanWind'] for x in calm):.3g}**. Les compteurs de tests / réutilisations de carte solaire sont conservés par frame ; le mouvement de l’avatar impose aussi des recentrages, donc ces passages ne mesurent pas une économie à caméra immobile."
comp=f"Le bundle de production du commit propre **`{compiled['identity']['expected']['commit'][:7]}`** passe chargement du monde, déplacement, arrêt sans dérive, hauteur d’œil, cycle de caméras, son, profils et viewport mobile. L’identité embarquée 17D passe **quatre formats**, sans recouvrement des contrôles ni requête de métadonnées externe. La galerie décode les **soixante JPEG de comparaison** et les **six vidéos** (décodage complet, métadonnées et seek), avec audio dans les trois extraits de marche ; ses quatre formats n’ont pas de débordement horizontal. [Validation compilée](mission-17-evidence/final/compiled-validation.json) · [Validation des médias et formats](mission-17-evidence/final/media-validation.json)."
names={'isole-5m':'Arbre seul à 5 m','groupe-15m':'Plusieurs arbres à 15 m','groupe-40m':'Groupe à 40 m','lisiere-100m':'Lisière à 100 m','foret-lointaine':'Forêt lointaine','aerienne':'Vue du ciel','berge':'Berges','village':'Village','pente':'Pente boisée','sous-bois':'Sous-bois dense'}
gallery='<details>\n<summary>Ouvrir les trente paires avant/après directement dans GitHub</summary>\n\n'
for id,label in names.items():
 gallery+='### '+label+'\n\n| Saison | Mission 16 | Mission 17D |\n| --- | --- | --- |\n'
 for month,season in [('06','Été'),('10','Automne'),('01','Hiver')]:gallery+=f'| {season} | ![{label}, {season}, Mission 16](mission-17-evidence/final/{id}-{month}-m16.jpg) | ![{label}, {season}, Mission 17D](mission-17-evidence/final/{id}-{month}-after.jpg) |\n'
 gallery+='\n'
gallery+='</details>\n\n![Bibliothèque métrique de onze familles](mission-17-evidence/final/library.jpg)\n\n| Printemps | Été | Automne | Hiver |\n| --- | --- | --- | --- |\n| '+ ' | '.join(f'![{season}](mission-17-evidence/final/season-{season}.jpg)' for season in ['spring','summer','autumn','winter'])+' |'
text=Path('scripts/templates/mission-17d-report.txt').read_text()
for key,value in [('PERFORMANCE','\n'.join(lines)),('COSTS',cost),('ALLOCATIONS',alloc),('SOAK',soak),('MEMORY',memory),('COMPILED',comp),('GALLERY',gallery)]:text=text.replace('@@'+key+'@@',value)
assert '@@' not in text
Path('docs/mission-17.md').write_text(text)
print('Final report generated from measured 17D results')
